(() => {
 'use strict';
 const C=window.AnalysisResponseCore,L=window.AnalysisResponseLabs,S=window.AnalysisScenarios,G=window.AnalysisModelGuides;
 const {p,f,table,qrg,dyn,beamStructure}=window.AnalysisResponseLessonHelpers;
 const data={
  'trans-short':{title:'短い荷重：除荷後に最大値が出る',sol:109,tau:.005,point:'荷重が消えた後にも質量が動き続け、最大変位が現れることがあります。荷重の最大時刻だけを出力して終わらないようにします。',change:'先端−Zへ18 N、0.005 sで除荷。初期変位・初期速度0。',mistake:['荷重0になったので、その後の結果は不要と思った','除荷時の変位と速度が自由振動の初期条件になります。十分長く計算し、載荷中と除荷後の両方の最大値を確認します。']},
  'trans-long':{title:'長い荷重：急な載荷と除荷時刻を分ける',sol:109,tau:.05,point:'荷重を長く保持しても、急に加えれば載荷直後は動的に振れます。除荷後の振幅は、除く時刻の変位と速度で変わります。',change:'荷重継続0.05 s。短い荷重と同じ梁・減衰・時間刻み。',mistake:['長時間荷重なので静解析と同じ最大値と思った','初期状態0から急に荷重を加えることと、最初から静的平衡にあることは別です。立上り時間と保持時間を区別します。']},
  'trans-modal':{title:'モード法：時間刻みより先に必要な基底を確認',sol:112,tau:.05,point:'時間刻みを細かくしても、切り捨てたモードは戻りません。急な荷重に対する局所応力や加速度も別々に収束させます。',change:'長い荷重と同じ物理条件、既存EIGRL ND=6。',mistake:['Δtを小さくすれば直接法と必ず一致すると思った','基底不足、残余ベクトル、減衰変換、初期条件をそろえてから時間刻みを比較します。先端変位だけの一致では局所応力を保証できません。']},
  'trans-coarse':{title:'粗い時間刻み・粗い保存：別々の見落とし',sol:109,tau:.05,point:'積分する間隔と結果を保存する間隔は別です。NOだけを小さくしても、粗い積分の位相誤差は直りません。',change:'理論比較でΔtを0.005／0.001／0.0005／0.0001 sへ変更。NOは独立に変更。',mistake:['NO=1なら精密な解析と思った','NO=1は毎計算点を保存するだけです。時間積分の精度はDTなどで変わります。DTを小さくしてもNOが大きければ、保存結果でピークを見落とします。']},
  'trans-ramp':{title:'有限の立上り時間：同じピーク荷重でも応答が変わる',sol:109,tau:.05,point:'荷重を加える速さは高周波成分と過渡応答を変えます。実物の立上りを、理由なく瞬時の段差に置き換えないようにします。',change:'18 Nまで0.05 sで上げ、次の0.05 sで0へ戻す三角波。矩形0.05 sとピーク・力積をそろえる。',mistake:['ピーク18 Nと力積が同じなら応答も同じと思った','力積だけで応答を近似できるのは、荷重が対象周期に比べ十分短い場合などに限られます。波形の周波数成分が違えば応答も変わります。']}
 };
 const s=S.transient;
 for(const id of ['trans-coarse','trans-ramp'])s.models.push({id,diagram:id==='trans-ramp'?'response-ramp':'pulse-long',theoretical:true});
 for(const m of s.models){
  const d=data[m.id],modal=d.sol===112,id=m.id;
  m.title=d.title;m.sol=d.sol;m.takeaway=d.point;
  m.diagramCaption='左の根元G1は123456固定。先端G13/T3へ−Z方向の力。観測するT3は負方向に変形します。操作図だけは荷重方向を正に取り、u=−T3として読みます。';
  m.conditions=[['共通の梁','L=360 mm、断面36×6 mm、E=70,000 MPa、ρ=2.70×10⁻⁹ tonne/mm³。弱軸I=648 mm⁴。'],['荷重・変更点',d.change],['減衰と計算区間','既存梁はG=.04、W3=239.3 rad/s。構造減衰を等価粘性へ換算。0〜0.2 s、基準DT=.0005 s、NO=1。'],['理論比較の条件','操作図は初期変位・速度0の1自由度近似。静たわみ18/k=6.1714 mm、fₙ≈38.1 Hzを用います。高次モード・応力分布・MSCの実行結果は表しません。']];
  m.results=['T3の符号を保って時刻歴を読み、載荷中と除荷後の最大値を別々に求めます。','荷重の変化時刻、変位、速度、加速度を同じ時間軸で対応させます。','NO×DTが保存間隔です。計算点での最大値と保存点の最大値は一致しないことがあります。',modal?'基底数・残余ベクトル・時間刻みの3つを別々に変え、直接法と同じ条件で比較します。':'時間刻みを半分にして、最大値だけでなくピーク時刻・振動周期・位相のずれを比較します。','支持反力と外力は瞬間的に同じとは限りません。慣性力と減衰力を含む動的釣合いで確認します。'];
  m.check=[['CASE_TSTEP','時間刻みセット'],['TSTEP','計算と保存の間隔'],['TLOAD1','荷重の種類・参照'],['TABLED1','波形と除荷後の値'],['PARAM_W3','換算する角振動数'],['CASE_DISPLACEMENT','時刻歴出力'],...(modal?[['EIGRL','基底'],['CASE_RESVEC','残余ベクトル']]:[])];
  G[id]={items:[d.point,d.change,'同じ物理条件で、荷重波形・基底・積分刻み・保存間隔を一つずつ確認します。'],
   explanation:()=>p(d.point)+p('時刻歴では外力P(t)と初期状態を与え、変位u・速度u̇・加速度üを時間に沿って求めます。')+
    f('Mü(t) + Bu̇(t) + Ku(t) = P(t)、u(0)=0、u̇(0)=0')+
    (modal?p('SOL 112ではu≈Φqと置き、Φᵀを掛けます。質量・剛性・減衰・荷重を同じ基底で写し、求めたq(t)から物理変位を復元します。減衰行列が非対角ならモード間の連成は残ります。')+
     f('M̄q̈ + B̄q̇ + K̄q = ΦᵀP(t)、u≈Φq'):
     p('SOL 109は拘束処理後の物理変数系を時間積分します。モード打切りはありませんが、有限要素の空間離散化と時間積分の誤差は残ります。'))+
    p('矩形波の意味を無減衰1自由度で先に確かめます。静たわみu_s=P₀/k、固有角振動数ωₙ=√(k/m)。荷重が続く間は、初期状態0を満たす解が次の式です。')+
    f('0≤t<τ：u(t)/u_s = 1 − cos(ωₙt)')+
    p('τで荷重を除く操作は、同じ大きさの負の段差をτだけ遅らせて加えることです。線形性から2つの段差応答を重ねます。')+
    f('t≥τ：u/u_s = [1−cos(ωₙt)] − [1−cos(ωₙ(t−τ))]')+
    f('= 2 sin(ωₙτ/2) sin(ωₙt−ωₙτ/2)')+
    p('したがって除荷後の振幅は2|sin(πτ/Tₙ)|倍。τ=Tₙなら理想無減衰系の除荷後振幅は0ですが、載荷中には2倍まで動いています。減衰ありや多自由度の全体が0になるという意味ではありません。')+
    p('τ≪Tₙのときだけsin(ωₙτ/2)≈ωₙτ/2となり、力積J=P₀τによるA≈J/(mωₙ)の近似へつながります。既存の短い荷重τ/T₁≈0.19を、無条件に「力積だけで決まる」と扱いません。')+
    f('小減衰の段差：u/u_s = 1 − e^(−ζωₙt)[cos(ω_dt)+ζ/√(1−ζ²) sin(ω_dt)]')+
    p('ω_d=ωₙ√(1−ζ²)。矩形波はこの式でも段差2つの差として求めます。操作図のζは近似系の粘性減衰比で、PARAM,Gの数値そのものではありません。')+
    L.render(id,'time')+
    p('平均加速度Newmark法の独立実験は、uₙ₊₁=uₙ+Δtvₙ+Δt²(aₙ+aₙ₊₁)/4、vₙ₊₁=vₙ+Δt(aₙ+aₙ₊₁)/2を釣合いへ代入して次の時刻を求めます。無条件安定でも時間精度を保証しません。NastranのSOL・連成/非連成によって実際の積分方式は異なるため、この図はその内部実装の再現ではありません。')+
    p('構造減衰を過渡へ換算すると、今回の全体GではB_eq=(G/W3)K。j次の粘性減衰比はζⱼ=Gωⱼ/(2W3)です。W3を第1角振動数へ合わせた場合でも、高次すべてが2%になるわけではありません。')+
    f('W3=239.3 rad/s ≈ 2π×38.1 Hz、ζⱼ=Gωⱼ/(2W3)'),
   inputReview:[
    ['解析と選択',[['EXEC_SOL_'+d.sol,modal?'SOL 112：実モードへ縮約した時刻歴。':'SOL 109：物理変数で時刻歴を解く。'],['EXEC_CEND','ExecutiveとCase Controlの境界。'],['CASE_SUBCASE','荷重・拘束・時間・出力を同じケースで対応。'],['CASE_SPC','SPC=10→根元固定。'],['CASE_DLOAD','DLOAD=50→TLOAD1 SID50。この単独波形ではBulk DLOADを経由しません。'],['CASE_TSTEP','TSTEP=60→Bulk TSTEP SID60。']]],
    ['構造・質量・支持',beamStructure],
    ['時間波形と倍率',[['TLOAD1','SID50、EXCITEID51、TID52。TYPEは荷重を表すLOAD／0。US0・VS0は強制運動の係数で、通常の力加振モデルの初期変位・速度欄ではありません。'],['DAREA','SID51、G13/C3へ−18 N。TABLED1の倍率を掛けて時間ごとの力になります。'],['TABLED1',id==='trans-ramp'?'理論比較は0→1→0の線形区間。終点後も0を保つ点を置き、意図しない外挿を防ぎます。':'TID52：時刻0から'+d.tau+' sまで1、その後0。既存表は除荷時刻を重複して段差を表します。不連続点そのものの値と前後の値を混同しません。'],['DLOAD','複数の波形を重ねる場合のBulkカード。各TLOADiのSIDとS×Siを確認。既存の単独荷重では未使用です。'],['TLOAD2','解析式で波形を定義する代替。TLOAD1の表をそのままTLOAD2の欄へ移しません。'],['DELAY','必要時の開始遅れ。荷重開始が計算区間の外になっていないか確認します。']]],
    ['時間・減衰・基底',[['TSTEP','SID60。基準はN=400、DT=.0005 s、NO=1。Nは時間増分の回数で、最終時刻N×DT=.2 s。NOは毎NO刻みの保存です。'],['PARAM_G','既存値.04。過渡では構造減衰から等価粘性へ換算する設定を合わせます。'],['PARAM_W3','239.3 rad/s。Hzの38.1をそのまま入れると換算粘性が約2π倍になります。値を変えると物理的な減衰モデルも変わります。'],...(modal?[['CASE_METHOD','METHOD=30で実モードの基底を選択。'],['EIGRL','SID30、ND6が既存基準。最高保持振動数とモード形を確認し、必要に応じて増やします。'],['CASE_RESVEC','既存過渡モデルには明示指定なし。使用版の有効設定を結果で確認し、直接法比較では補完の有無を記録。周波数応答のRESVEC=NOを勝手に同一視しません。'],['CASE_SDAMPING','モード減衰の表を使う場合の選択。G/W3と不用意に重複させません。'],['TABDMP1','TYPEと値を照合。全モード一定のζと、G/W3由来のζⱼ∝ωⱼは別の減衰モデルです。']]:[])]],
    ['結果',[['CASE_DISPLACEMENT','同じGRID・T3の時刻歴を出力。SORT2は並び順で、計算刻みは変えません。'],['CASE_VELOCITY','除荷時の速度を確認。荷重0でも変位が増える理由を追います。'],['CASE_ACCELERATION','単位と高周波成分を確認。変位が合うだけでは加速度の精度を保証しません。'],['CASE_FORCE','ばね・梁の内力。載荷直後や除荷直後も確認。'],['CASE_SPCFORCES','支持反力。慣性力・減衰力を含めて力の収支を照合。'],['PARAM_POST','必要な結果ファイルへの出力設定。時間刻みや出力要求の代わりではありません。']]]
   ],
   verify:['初期状態、静たわみ、固有周期、質量と拘束を確認します。','TLOAD1→DAREA→TABLED1の倍率・符号・開始・終了・外挿を確認します。','N×DTで計算終了時刻、NO×DTで保存間隔を別々に計算します。',modal?'基底数、残余ベクトル、減衰則をそろえて直接法と比較します。':'減衰の種類とW3の角周波数単位を確認します。','時間刻みを半分にし、最大値・時刻・周期・位相を確認。さらにNOを小さくして保存による見落としを調べます。','必要な応力・加速度・反力についても独立に収束確認します。'],
   resultExtra:()=>table(['比較','読み方'],[['荷重が0になった後','u(τ)とv(τ)から自由振動が続く。荷重最大時刻だけを評価しない。'],['静たわみとの比','急な段差は無減衰1自由度で最大2倍。任意の波形・全構造に一律2倍を適用しない。'],['細かい積分・粗い保存','積分は正確でも表示ピークが小さくなる。NOを変えて確認。'],['粗い積分・細かい保存','点が多く見えても精度は回復しない。DTを変えて確認。'],['力積が同じ波形','短時間近似の適用を確認。ピーク・持続・立上り・スペクトルを分ける。']]),
   pitfalls:[d.mistake,['TSTEPのNだけを増やして精度を上げたつもりになった','DTを固定してNを増やすと計算時間が延びます。精度比較では終点をそろえ、DTを小さくしてNを増やします。'],['W3へHzの値を入れた','W3は角振動数。ω=2πfを通して換算します。'],['TABLED1の最後を1のまま終えた','表外へ外挿され、荷重が残ることがあります。必要な時間区間と除荷後の0を明示します。'],['US0・VS0を通常の初期変位・速度と思った','TLOAD1では強制運動の初期係数です。自由度全体の初期状態の指定とは別です。']]
  };
 }
 s.summary='荷重の継続・立上り、保持モード、積分刻みと保存間隔を切り分け、過渡応答の見落としを診断します。';
 s.shared='既存の片持ち梁と18 Nを基準に、変更する条件を1つずつ比較します。操作図は独立した1自由度近似です。';
 s.columns=['モデル','変更点','最初に確認'];s.rows=s.models.map(m=>[m.title,data[m.id].change,data[m.id].mistake[0]]);
 s.compare='同じ単位・初期状態・荷重波形・減衰・計算時間で比較。基底と時間と保存を同時に変えないようにします。';
 s.sources=[dyn(230,'直接過渡応答'),dyn(232,'構造減衰の換算'),dyn(234,'モード過渡応答'),dyn(258,'時間刻み'),dyn(264,'基底と残余ベクトル'),qrg(3027,'TLOAD1'),qrg(3050,'TSTEP')];
 const common=window.AnalysisScenarioGuides.transient;
 common.basics=[['この記事で分かること',[s.summary,'荷重を除いた後の動きと初期条件をつなげます。','必要な最大値を見落とさない計算・保存の条件を選びます。']],['対象範囲',['線形構造の過渡応答。接触開閉や塑性など、状態で剛性が変わる問題はここで扱いません。','操作図は平均加速度法と解析解の独立比較で、MSC本体の実行結果ではありません。']]];
 common.terms=[['DT','時間積分の刻み。'],['NO','何刻みごとに結果を保存するか。'],['W3','構造減衰を換算する角振動数。'],['初期状態','開始時の変位と速度。荷重波形とは別に必要。']];common.steps=G['trans-long'].verify;
 for(const id of ['trans-coarse','trans-ramp']){
  const map=JSON.parse(JSON.stringify(window.AnalysisRelationMaps['trans-long']));
  map.scope='既存梁の条件を比較する理論用のカード構成。新規DAT・MSC実行結果は未収録です。';
  for(const panel of map.panels)for(const node of panel.nodes){
   if(node.card==='TSTEP'&&id==='trans-coarse')node.detail='SID60 / 40×.005 s / NOを別に比較';
   if(node.card==='TABLED1'&&id==='trans-ramp')node.detail='TID52 / 0→1→0 / .05 sずつ';
  }
  window.AnalysisRelationMaps[id]=map;window.AnalysisScenarioRelationKeys.push(id);
 }
})();